<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import type { Student } from '$lib/types'; let students:Student[]=[]; let error=''; let notice=''; let form={firstName:'',lastName:'',preferredName:'',birthDate:'',ageGroup:'Kids',joinDate:new Date().toISOString().slice(0,10),uniformSize:'',beltSize:''}; async function load(){try{students=await api<Student[]>('/api/students');}catch(e){error=e instanceof Error?e.message:'Could not load students.';}} async function create(){error='';notice='';try{await api('/api/students',{method:'POST',body:JSON.stringify({...form,birthDate:form.birthDate||null,joinDate:form.joinDate||null,beltRankId:null})});notice='Student created.';form={firstName:'',lastName:'',preferredName:'',birthDate:'',ageGroup:'Kids',joinDate:new Date().toISOString().slice(0,10),uniformSize:'',beltSize:''};await load();}catch(e){error=e instanceof Error?e.message:'Could not create student.';}} async function deactivate(id:string){if(!confirm('Deactivate this student?'))return;try{await api(`/api/students/${id}/deactivate`,{method:'POST'});await load();}catch(e){error=e instanceof Error?e.message:'Could not deactivate student.';}} onMount(load);</script>
<div class="toolbar"><div><span class="eyebrow">PEOPLE</span><h2>Students</h2></div></div>{#if error}<div class="error">{error}</div>{/if}{#if notice}<div class="status">{notice}</div>{/if}<section class="card"><h3>Create student</h3><form class="form-grid" on:submit|preventDefault={create}><label>First name<input bind:value={form.firstName} required /></label><label>Last name<input bind:value={form.lastName} required /></label><label>Preferred name<input bind:value={form.preferredName} /></label><label>Age group<select bind:value={form.ageGroup}><option value="Kids">Kids</option><option value="TeensAdults">Teens & Adults</option></select></label><label>Birth date<input type="date" bind:value={form.birthDate} /></label><label>Join date<input type="date" bind:value={form.joinDate} required /></label><label>Uniform size<input bind:value={form.uniformSize} /></label><label>Belt size<input bind:value={form.beltSize} /></label><div class="full"><button class="button">Create student</button></div></form></section><section class="card"><div class="section-heading"><h3>Active roster</h3><span class="pill">{students.length}</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Age group</th><th>Rank</th><th>Join date</th><th></th></tr></thead><tbody>{#each students as student}<tr><td><strong>{student.preferredName||student.firstName} {student.lastName}</strong></td><td>{student.ageGroup}</td><td>{student.beltRank||'Not assigned'}</td><td>{new Date(student.joinDate).toLocaleDateString()}</td><td><button class="button danger small-button" on:click={()=>deactivate(student.id)}>Deactivate</button></td></tr>{:else}<tr><td colspan="5" class="muted">No students yet.</td></tr>{/each}</tbody></table></div></section>
